#!/usr/bin/env python3
"""
EpiTop1 -- 500-Protein Epitope Prediction Benchmark
====================================================

Tests both the core and bio prediction pipelines against 500 proteins
with experimentally validated linear B-cell epitopes curated from IEDB
and the primary literature.

Categories
----------
  Proteins   1-10 : Original panel (TaSP, SARS-CoV-2 RBD, HIV gp41, ...)
  Proteins  11-40 : Viral antigens
  Proteins  41-65 : Bacterial antigens
  Proteins  66-80 : Parasitic & fungal antigens
  Proteins 81-100 : Model, mammalian & allergen proteins
  Proteins 101-150: More viral proteins (coronaviruses, HIV, influenza, filoviruses, etc.)
  Proteins 151-220: More bacterial proteins (mycobacteria, staphylococci, streptococci, etc.)
  Proteins 221-300: Parasites and fungi (plasmodium, toxoplasma, leishmania, etc.)
  Proteins 301-400: Mammalian, model & allergen proteins (cytokines, receptors, allergens, etc.)
  Proteins 401-500: Additional diverse proteins (toxins, vaccine candidates, diagnostic antigens, etc.)

Usage:
    python test_benchmark_500.py
"""

from __future__ import annotations

import sys, os, textwrap
from dataclasses import dataclass
from typing import List, Tuple

import numpy as np

PROJECT_ROOT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, PROJECT_ROOT)

from core.scoring import GlobalScorer
from core.epitope_selector import EpitopeSelector
